"""Dashboard novo, em gráficos: 4 números no topo e 8 gráficos. Rode na raiz: python aplicar_dashboard_graficos.py"""
from pathlib import Path

NOVOS = {'apps/painel/graficos.py': '"""Dados dos 8 gráficos do dashboard.\n\nAs funções `montar_*` recebem dados já lidos (fáceis de testar) e devolvem o formato que o\nChart.js usa. `todos()` lê o banco e monta cada gráfico à parte: se um falhar, ele some e os\noutros continuam.\n"""\n\nimport logging\nfrom datetime import date, datetime, timedelta, timezone\n\nfrom dominio import limiares\nfrom dominio.distritos import ROMANOS, nome_distrito\n\nlogger = logging.getLogger(__name__)\n\nCHUVA_HORA_MODERADA = 2.5   # mm/h: daqui para cima a chuva já é moderada\nJANELA_NORMAL_DIAS = 3      # a normal de um dia usa ±3 dias, para não oscilar demais\nANOS_HISTORICO = (2014, 2024)\nMESES = ["jan", "fev", "mar", "abr", "mai", "jun", "jul", "ago", "set", "out", "nov", "dez"]\n\n\n# 1. Chuva x maré nas próximas 48 h -----------------------------------------------------------\ndef chuva_mare_48h(proximas):\n    """As horas em que chuva moderada e maré alta coincidem ficam marcadas como críticas."""\n    if not proximas:\n        return None\n    limiar = proximas.get("limiar_mare")\n    criticas = [c is not None and m is not None and limiar is not None\n                and c >= CHUVA_HORA_MODERADA and m >= limiar\n                for c, m in zip(proximas["chuva"], proximas["mare"])]\n    return {**proximas, "criticas": criticas, "horas_criticas": sum(criticas)}\n\n\n# 2. Quanto falta para o gatilho, por distrito ------------------------------------------------\ndef distancia_gatilho(situacao):\n    linhas = sorted(situacao or [], key=lambda d: d["codigo"])\n    if not linhas:\n        return None\n    return {"distritos": [d["nome"] for d in linhas],\n            "medido_72h": [d.get("chuva_72h_mm") for d in linhas],\n            "previsto_24h": [d.get("previsao_24h_mm") for d in linhas],\n            "limiares": {"encharcado": limiares.SOLO_ENCHARCADO_MM, "forte": limiares.CHUVA_FORTE,\n                         "muito_forte": limiares.CHUVA_MUITO_FORTE}}\n\n\n# 3. Chuva dos últimos 30 dias x normal histórica ---------------------------------------------\ndef normal_por_dia_do_ano(chuva_diaria_historica):\n    """{(mes, dia): média da pior chuva do dia na cidade}, com janela de ±3 dias."""\n    por_dia = {}\n    for data, mm in chuva_diaria_historica:\n        if mm is not None:\n            por_dia.setdefault((data.month, data.day), []).append(mm)\n    normal = {}\n    base = date(2001, 1, 1)  # ano não bissexto: 29/02 usa a janela dos vizinhos\n    for i in range(365):\n        d = base + timedelta(days=i)\n        valores = []\n        for k in range(-JANELA_NORMAL_DIAS, JANELA_NORMAL_DIAS + 1):\n            v = base + timedelta(days=(i + k) % 365)\n            valores += por_dia.get((v.month, v.day), [])\n        if valores:\n            normal[(d.month, d.day)] = round(sum(valores) / len(valores), 1)\n    normal[(2, 29)] = normal.get((2, 28))\n    return normal\n\n\ndef chuva_30_dias(recente, normal, hoje):\n    """recente = chuva_diaria(30) do painel; normal = normal_por_dia_do_ano(...)."""\n    if not recente:\n        return None\n    datas = [hoje - timedelta(days=29 - i) for i in range(30)]\n    pior = next((s["valores"] for s in recente["series"] if s["tipo"] == "line"), [])\n    normais = [normal.get((d.month, d.day)) for d in datas]\n    validos = [(p, n) for p, n in zip(pior, normais) if p is not None and n is not None]\n    total, total_normal = sum(p for p, _ in validos), sum(n for _, n in validos)\n    return {"rotulos": recente["rotulos"], "chuva": pior, "normal": normais,\n            "total_mm": round(total, 1), "normal_mm": round(total_normal, 1),\n            "razao": round(total / total_normal, 2) if total_normal else None}\n\n\n# 4. Onde estamos no ano: atendimentos ---------------------------------------------------------\ndef sazonalidade_atendimentos(semanais, previsao_docs, hoje):\n    """semanais = [(ano, semana, total da cidade)]; previsão = docs de gold_demanda_previsao."""\n    por_semana = {}\n    for ano, semana, total in semanais:\n        por_semana.setdefault(min(semana, 52), []).append(total)\n    if not por_semana:\n        return None\n    semanas = list(range(1, 53))\n    serie = [por_semana.get(s, []) for s in semanas]\n    # a semana marcada é a da previsão gravada (pode ser uma demonstração); sem previsão, a de hoje\n    referencia = date.fromisoformat(previsao_docs[0]["inicio_semana"][:10]) if previsao_docs else hoje\n    atual = min(referencia.isocalendar()[1], 52)\n    previsto = round(sum(d["previsto"] for d in previsao_docs)) if previsao_docs else None\n    return {"rotulos": [f"S{s}" for s in semanas],\n            "media": [round(sum(v) / len(v)) if v else None for v in serie],\n            "minimo": [min(v) if v else None for v in serie],\n            "maximo": [max(v) if v else None for v in serie],\n            "semana_atual": atual, "previsto": previsto,\n            "completa": all(d.get("completa") for d in previsao_docs) if previsao_docs else False}\n\n\n# 5. Arboviroses: este ano x ano anterior ------------------------------------------------------\ndef arboviroses_ano_a_ano(semanas_docs):\n    if not semanas_docs:\n        return None\n    ano = max(d["ano"] for d in semanas_docs)\n    serie = {(d["ano"], d["semana"]): d for d in semanas_docs}\n    rotulos = list(range(1, 54))\n    ultimo = max(d["semana"] for d in semanas_docs if d["ano"] == ano)\n    return {"rotulos": [f"SE {s}" for s in rotulos], "ano": ano, "ano_anterior": ano - 1,\n            "atual": [serie[(ano, s)]["estimados"] if (ano, s) in serie else None for s in rotulos],\n            "anterior": [serie[(ano - 1, s)]["estimados"] if (ano - 1, s) in serie else None for s in rotulos],\n            "nivel": [serie[(ano, s)].get("nivel") if (ano, s) in serie else None for s in rotulos],\n            "ultima_semana": ultimo}\n\n\n# 6. Calendário de risco: distrito x mês -------------------------------------------------------\ndef calendario_calor(por_mes, mes_atual):\n    if not por_mes:\n        return None\n    celulas = {(m["distrito_codigo"], m["mes"]): m.get("indice") for m in por_mes}\n    def tom(v):\n        if v is None:\n            return "vazio"\n        return "t4" if v >= 1.6 else "t3" if v >= 1.2 else "t2" if v >= 0.8 else "t1"\n    linhas = [{"distrito": nome_distrito(c),\n               "celulas": [{"valor": celulas.get((c, m)), "tom": tom(celulas.get((c, m))), "atual": m == mes_atual}\n                           for m in range(1, 13)]}\n              for c in range(1, len(ROMANOS) + 1)]\n    return {"meses": MESES, "mes_atual": mes_atual, "linhas": linhas}\n\n\n# 7. Alertas dos últimos 30 dias ---------------------------------------------------------------\ndef alertas_30_dias(alertas, sem_acao, hoje):\n    datas = [hoje - timedelta(days=29 - i) for i in range(30)]\n    contagem = {}\n    for a in alertas:\n        dia = a["criado_em"].date() if isinstance(a["criado_em"], datetime) else a["criado_em"]\n        contagem[(dia, a["nivel"])] = contagem.get((dia, a["nivel"]), 0) + 1\n    return {"rotulos": [d.strftime("%d/%m") for d in datas],\n            "alto": [contagem.get((d, "ALTO"), 0) for d in datas],\n            "medio": [contagem.get((d, "MÉDIO"), 0) for d in datas],\n            "total": sum(contagem.values()), "sem_acao": sem_acao}\n\n\ndef _data_br(iso):\n    try:\n        return date.fromisoformat(str(iso)[:10]).strftime("%d/%m/%Y")\n    except ValueError:\n        return iso\n\n\n# 8. Demanda prevista por distrito x normal ----------------------------------------------------\ndef demanda_por_distrito(previsao_docs):\n    if not previsao_docs:\n        return None\n    docs = sorted(previsao_docs, key=lambda d: d["distrito_codigo"])\n    return {"distritos": [d["distrito"] for d in docs],\n            "previsto": [d["previsto"] for d in docs], "normal": [d.get("normal") for d in docs],\n            "real": [d.get("real") for d in docs] if any(d.get("real") is not None for d in docs) else None,\n            "inicio": _data_br(docs[0]["inicio_semana"]), "fim": _data_br(docs[0]["fim_semana"]),\n            "completa": all(d.get("completa") for d in docs)}\n\n\n# Números do topo ------------------------------------------------------------------------------\ndef indicadores(meteo, alertas_abertos, sem_acao, arbo):\n    return {"chuva_24h": meteo.get("chuva_24h") if meteo else None,\n            "chuva_24h_zona": meteo.get("chuva_24h_zona") if meteo else None,\n            "previsao_24h": meteo.get("previsao_24h") if meteo else None,\n            "previsao_24h_zona": meteo.get("previsao_24h_zona") if meteo else None,\n            "alertas_abertos": alertas_abertos, "sem_acao": sem_acao,\n            "arbo_estimados": arbo.get("estimados") if arbo else None,\n            "arbo_nivel": arbo.get("nivel_nome") if arbo else None,\n            "arbo_semana": arbo.get("semana") if arbo else None}\n\n\n# Leitura do banco -----------------------------------------------------------------------------\ndef _bloco(nome, funcao):\n    try:\n        return funcao()\n    except Exception:  # noqa: BLE001 - o gráfico que falha some; o dashboard continua\n        logger.exception("Falha ao montar o gráfico %s do dashboard", nome)\n        return None\n\n\ndef _chuva_historica(banco):\n    """Pior chuva do dia na cidade (maior entre os distritos), 2014-2024."""\n    return [(d["_id"], d["mm"]) for d in banco["gold_ml_distrito_dia"].aggregate([\n        {"$match": {"ano": {"$gte": ANOS_HISTORICO[0], "$lte": ANOS_HISTORICO[1]}, "chuva_dia_mm": {"$ne": None}}},\n        {"$group": {"_id": "$data", "mm": {"$max": "$chuva_dia_mm"}}}])]\n\n\ndef _atendimentos_semanais(banco):\n    return [(d["_id"]["ano"], d["_id"]["semana"], d["total"]) for d in banco["gold_ml_distrito_dia"].aggregate([\n        {"$match": {"ano": {"$gte": 2015, "$lte": ANOS_HISTORICO[1]}}},\n        {"$group": {"_id": {"ano": {"$isoWeekYear": "$data"}, "semana": {"$isoWeek": "$data"}},\n                    "total": {"$sum": "$atendimentos_reativos"}, "dias": {"$sum": 1}}},\n        {"$match": {"dias": {"$gte": 7 * len(ROMANOS)}}}])]\n\n\ndef todos(proximas, situacao):\n    from django.db.models import Count\n\n    from apps.alertas.models import Alerta\n    from apps.fontes import painel_chuva\n    from apps.fontes.repositorios import arboviroses as repo_arbo\n    from apps.fontes.repositorios import calendario as repo_cal\n    from apps.fontes.repositorios import conexao\n    from apps.fontes.repositorios import demanda as repo_demanda\n\n    hoje = date.today()\n    banco = _bloco("banco", conexao.banco)\n    previsao = _bloco("demanda", repo_demanda.previsao) or []\n    abertos = Alerta.objects.exclude(status=Alerta.Status.ENCERRADO)\n    sem_acao = _bloco("sem ação", lambda: abertos.annotate(n=Count("acoes")).filter(n=0).count())\n    desde = datetime.now(timezone.utc) - timedelta(days=30)\n    return {\n        "indicadores": _bloco("indicadores", lambda: indicadores(\n            painel_chuva.resumo_meteo(), abertos.count(), sem_acao, repo_arbo.resumo_semana_cidade())),\n        "g1": _bloco("chuva x maré", lambda: chuva_mare_48h(proximas)),\n        "g2": _bloco("gatilho", lambda: distancia_gatilho(situacao)),\n        "g3": _bloco("chuva 30 dias", lambda: chuva_30_dias(\n            painel_chuva.chuva_diaria(30), normal_por_dia_do_ano(_chuva_historica(banco)), hoje)),\n        "g4": _bloco("sazonalidade", lambda: sazonalidade_atendimentos(_atendimentos_semanais(banco), previsao, hoje)),\n        "g5": _bloco("arboviroses", lambda: arboviroses_ano_a_ano(repo_arbo.semanas_dois_anos())),\n        "g6": _bloco("calendário", lambda: calendario_calor(repo_cal.por_mes(), hoje.month)),\n        "g7": _bloco("alertas", lambda: alertas_30_dias(\n            Alerta.objects.filter(criado_em__gte=desde).values("nivel", "criado_em"), sem_acao or 0, hoje)),\n        "g8": _bloco("demanda", lambda: demanda_por_distrito(previsao)),\n    }\n', 'tests/test_dashboard_graficos.py': 'from datetime import date, datetime, timedelta, timezone\n\nimport pytest\n\nfrom apps.painel import graficos\n\n\ndef test_g1_marca_horas_criticas():\n    g = graficos.chuva_mare_48h({"rotulos": ["10h", "11h", "12h"], "chuva": [3, 1, 6], "mare": [2.4, 2.5, 2.0],\n                                 "limiar_mare": 2.3, "zona": "DS VII"})\n    assert g["criticas"] == [True, False, False] and g["horas_criticas"] == 1\n    assert graficos.chuva_mare_48h(None) is None\n\n\ndef test_g2_ordena_distritos_e_leva_limiares():\n    g = graficos.distancia_gatilho([{"codigo": 2, "nome": "DS II", "chuva_72h_mm": 40, "previsao_24h_mm": 10},\n                                    {"codigo": 1, "nome": "DS I", "chuva_72h_mm": None, "previsao_24h_mm": 3}])\n    assert g["distritos"] == ["DS I", "DS II"] and g["medido_72h"] == [None, 40]\n    assert set(g["limiares"]) == {"encharcado", "forte", "muito_forte"}\n\n\ndef test_g3_normal_com_janela_e_razao():\n    historico = [(date(2020, 11, d), 10.0) for d in range(1, 31)] + [(date(2021, 11, 15), 30.0)]\n    normal = graficos.normal_por_dia_do_ano(historico)\n    assert normal[(11, 15)] > normal[(11, 5)] and (2, 29) in normal\n    hoje = date(2026, 11, 27)\n    recente = {"rotulos": [str(i) for i in range(30)],\n               "series": [{"tipo": "bar", "valores": [0] * 30}, {"tipo": "line", "valores": [20.0] * 30}]}\n    g = graficos.chuva_30_dias(recente, normal, hoje)\n    assert len(g["normal"]) == 30 and g["razao"] > 1\n\n\ndef test_g4_sazonalidade_e_ponto_da_previsao():\n    semanais = [(2020, 21, 400), (2021, 21, 600), (2020, 47, 100)]\n    prev = [{"previsto": 50.4, "inicio_semana": "2024-05-20", "completa": True},\n            {"previsto": 49.8, "inicio_semana": "2024-05-20", "completa": True}]\n    g = graficos.sazonalidade_atendimentos(semanais, prev, date(2026, 11, 27))\n    assert g["media"][20] == 500 and g["minimo"][20] == 400 and g["maximo"][20] == 600\n    assert g["semana_atual"] == 21 and g["previsto"] == 100 and g["completa"]\n\n\ndef test_g5_ano_contra_ano_anterior():\n    docs = [{"ano": 2025, "semana": 1, "estimados": 80}, {"ano": 2026, "semana": 1, "estimados": 60, "nivel": 2},\n            {"ano": 2026, "semana": 2, "estimados": 65}]\n    g = graficos.arboviroses_ano_a_ano(docs)\n    assert g["ano"] == 2026 and g["atual"][:3] == [60, 65, None] and g["anterior"][0] == 80 and g["ultima_semana"] == 2\n\n\ndef test_g6_calor_tons_e_mes_atual():\n    g = graficos.calendario_calor([{"distrito_codigo": 1, "mes": 5, "indice": 1.7},\n                                   {"distrito_codigo": 1, "mes": 11, "indice": 0.5}], 11)\n    linha = g["linhas"][0]["celulas"]\n    assert linha[4]["tom"] == "t4" and linha[10]["tom"] == "t1" and linha[10]["atual"] and linha[0]["tom"] == "vazio"\n    assert len(g["linhas"]) == 8\n\n\ndef test_g7_conta_por_dia_e_nivel():\n    hoje = date(2026, 11, 27)\n    al = [{"nivel": "ALTO", "criado_em": datetime(2026, 11, 27, 10, tzinfo=timezone.utc)},\n          {"nivel": "MÉDIO", "criado_em": datetime(2026, 11, 27, 11, tzinfo=timezone.utc)},\n          {"nivel": "ALTO", "criado_em": datetime(2026, 11, 20, tzinfo=timezone.utc)}]\n    g = graficos.alertas_30_dias(al, 2, hoje)\n    assert g["alto"][-1] == 1 and g["medio"][-1] == 1 and g["alto"][-8] == 1 and g["total"] == 3 and g["sem_acao"] == 2\n\n\ndef test_g8_demanda_e_real_so_quando_existe():\n    docs = [{"distrito_codigo": 2, "distrito": "DS II", "previsto": 90, "normal": 80, "inicio_semana": "a", "fim_semana": "b"},\n            {"distrito_codigo": 1, "distrito": "DS I", "previsto": 20, "normal": 25, "inicio_semana": "a", "fim_semana": "b"}]\n    g = graficos.demanda_por_distrito(docs)\n    assert g["distritos"] == ["DS I", "DS II"] and g["real"] is None\n\n\n@pytest.mark.django_db\ndef test_dashboard_abre_com_os_graficos(client, monkeypatch):\n    from apps.painel import views\n    monkeypatch.setattr(views, "situacao_por_distrito", lambda: [])\n    monkeypatch.setattr(graficos, "todos", lambda p, s: {\n        "indicadores": graficos.indicadores({"chuva_24h": 12.5}, 3, 1, {"estimados": 72, "semana": 47, "nivel_nome": "amarelo"}),\n        "g1": graficos.chuva_mare_48h({"rotulos": ["10h"], "chuva": [3], "mare": [2.4], "limiar_mare": 2.3, "zona": "DS VII"}),\n        "g2": None, "g3": None, "g4": None, "g5": None,\n        "g6": graficos.calendario_calor([{"distrito_codigo": 1, "mes": 5, "indice": 1.7}], 11),\n        "g7": graficos.alertas_30_dias([], 1, date.today()), "g8": None})\n    html = client.get("/dashboard/").content.decode()\n    for trecho in ["1 · Chuva × maré nas próximas 48 h", "6 · Calendário de risco", "8 · Demanda prevista",\n                   "1 sem nenhuma ação registrada", \'id="d-g1"\', "1 hora crítica"]:\n        assert trecho in html, trecho\n'}
TROCAS = {'apps/fontes/repositorios/arboviroses.py': ('"""Leituras de arboviroses para as telas."""\n\nfrom . import conexao\n\nGOLD_SEMANA_CIDADE = "gold_arbovirose_semana_cidade"\n\n\ndef resumo_semana_cidade():\n    """A semana epidemiológica mais recente, já agregada pelo ETL.\n\n    Devolve None se o ETL ainda não rodou.\n    """\n    doc = conexao.banco()[GOLD_SEMANA_CIDADE].find_one({}, {"_id": 0}, sort=[("se", -1)])\n    if not doc:\n        return None\n    # semana epidemiológica é DATA, não horário: o valor gravado é meia-noite\n    # UTC e converter para o fuso local faria a semana começar no dia anterior\n    doc["inicio"] = doc["inicio"].date()\n    doc["fim"] = doc["fim"].date()\n    return doc\n\n\nSILVER_BAIRRO_ANO = "silver_arboviroses_bairro_ano"\n\n\ndef anos_por_bairro():\n    """Anos com dados por bairro (histórico do SINAN), em ordem."""\n    return sorted(conexao.banco()[SILVER_BAIRRO_ANO].distinct("ano"))\n\n\ndef por_bairro(ano, doencas):\n    """Casos prováveis por bairro e doença num ano."""\n    return list(conexao.banco()[SILVER_BAIRRO_ANO].find(\n        {"ano": ano, "doenca": {"$in": list(doencas)}},\n        {"_id": 0, "chave": 1, "doenca": 1, "provaveis": 1, "populacao": 1}))\n', '"""Leituras de arboviroses para as telas."""\n\nfrom . import conexao\n\nGOLD_SEMANA_CIDADE = "gold_arbovirose_semana_cidade"\n\n\ndef resumo_semana_cidade():\n    """A semana epidemiológica mais recente, já agregada pelo ETL.\n\n    Devolve None se o ETL ainda não rodou.\n    """\n    doc = conexao.banco()[GOLD_SEMANA_CIDADE].find_one({}, {"_id": 0}, sort=[("se", -1)])\n    if not doc:\n        return None\n    # semana epidemiológica é DATA, não horário: o valor gravado é meia-noite\n    # UTC e converter para o fuso local faria a semana começar no dia anterior\n    doc["inicio"] = doc["inicio"].date()\n    doc["fim"] = doc["fim"].date()\n    return doc\n\n\nSILVER_BAIRRO_ANO = "silver_arboviroses_bairro_ano"\n\n\ndef anos_por_bairro():\n    """Anos com dados por bairro (histórico do SINAN), em ordem."""\n    return sorted(conexao.banco()[SILVER_BAIRRO_ANO].distinct("ano"))\n\n\ndef por_bairro(ano, doencas):\n    """Casos prováveis por bairro e doença num ano."""\n    return list(conexao.banco()[SILVER_BAIRRO_ANO].find(\n        {"ano": ano, "doenca": {"$in": list(doencas)}},\n        {"_id": 0, "chave": 1, "doenca": 1, "provaveis": 1, "populacao": 1}))\n\n\ndef semanas_dois_anos():\n    """Todas as semanas do ano mais recente e do anterior, para comparar ano a ano."""\n    colecao = conexao.banco()[GOLD_SEMANA_CIDADE]\n    ultimo = colecao.find_one({}, {"ano": 1}, sort=[("se", -1)])\n    if not ultimo:\n        return []\n    return list(colecao.find({"ano": {"$gte": ultimo["ano"] - 1}},\n                             {"_id": 0, "ano": 1, "semana": 1, "estimados": 1, "nivel": 1}).sort("se", 1))\n'), 'apps/painel/static/painel/dashboard.js': ('// ============================================================================\n// GRÁFICO 1: Histórico de Chuva Diária\n// ============================================================================\nconst elDados = document.getElementById(\'dados-chuva-diaria\');\n\nif (elDados) {\n  const dados = JSON.parse(elDados.textContent);\n  const cores = [\'#93c5fd\', \'#1e3a8a\', \'#0ea5e9\', \'#14b8a6\', \'#6366f1\', \'#64748b\'];\n\n  // Função auxiliar para formatar valores em milímetros\n  const formatarMilimetros = (valor) => {\n    return `${valor.toLocaleString(\'pt-BR\', { minimumFractionDigits: 1, maximumFractionDigits: 1 })} mm`;\n  };\n\n  // 1.1 Configuração das linhas/barras de chuva\n  const datasetsSeries = dados.series.map((serie, index) => {\n    const corAtual = cores[index % cores.length];\n    const isBar = serie.tipo === \'bar\';\n\n    return {\n      label: serie.nome,\n      data: serie.valores,\n      type: serie.tipo || \'line\',\n      order: isBar ? 2 : 1,\n      borderColor: corAtual,\n      backgroundColor: isBar\n        ? serie.valores.map((_, j) => (j === serie.valores.length - 1 ? \'#dbeafe\' : corAtual))\n        : corAtual,\n      borderWidth: isBar ? 0 : 2.5,\n      borderRadius: 2,\n      pointRadius: 3,\n      tension: 0,\n      spanGaps: false, // dia sem coleta fica como lacuna, não como zero\n      segment: isBar ? undefined : {\n        borderDash: (ctx) => (ctx.p1DataIndex === serie.valores.length - 1 ? [5, 4] : undefined)\n      }\n    };\n  });\n\n  // 1.2 Configuração das linhas de limiares (linhas de referência horizontais)\n  const datasetsLimiares = (dados.limiares || []).map((limiar) => ({\n    type: \'line\',\n    label: `${limiar.nome} (${formatarMilimetros(limiar.mm)})`,\n    data: dados.rotulos.map(() => limiar.mm),\n    borderColor: limiar.cor,\n    borderDash: [6, 4],\n    borderWidth: 1.2,\n    pointRadius: 0,\n    order: 0\n  }));\n\n  // 1.3 Renderização do Gráfico\n  new Chart(document.getElementById(\'graficoChuva\'), {\n    type: \'line\',\n    data: {\n      labels: dados.rotulos,\n      datasets: [...datasetsSeries, ...datasetsLimiares]\n    },\n    options: {\n      responsive: true,\n      maintainAspectRatio: false,\n      interaction: { mode: \'index\', intersect: false },\n      plugins: {\n        legend: {\n          position: \'bottom\',\n          labels: { boxWidth: 12, font: { size: 11 } }\n        },\n        tooltip: {\n          callbacks: {\n            label: (contexto) => {\n              const valor = contexto.parsed.y;\n              return `${contexto.dataset.label}: ${valor === null ? \'sem dado\' : formatarMilimetros(valor)}`;\n            }\n          }\n        }\n      },\n      scales: {\n        x: { grid: { display: false } },\n        y: {\n          beginAtZero: true,\n          suggestedMax: 20, // a linha de chuva forte (18,6 mm) sempre aparece como referência\n          grid: { color: \'#f1f5f9\' },\n          ticks: { callback: (valor) => `${valor.toLocaleString(\'pt-BR\')} mm` }\n        }\n      }\n    }\n  });\n}\n\n\n// ============================================================================\n// GRÁFICO 2: Próximas 48h (Chuva Prevista × Maré)\n// ============================================================================\nconst el48 = document.getElementById(\'dados-48h\');\n\nif (el48) {\n  const d48 = JSON.parse(el48.textContent);\n\n  // Função auxiliar para formatar números com unidades (ex: \'mm\' ou \'m\')\n  const formatarValor = (valor, casasDecimais, unidade) => {\n    return `${valor.toLocaleString(\'pt-BR\', { minimumFractionDigits: casasDecimais, maximumFractionDigits: casasDecimais })} ${unidade}`;\n  };\n\n  // 2.1 Séries de Chuva e Maré\n  const series = [\n    {\n      type: \'bar\',\n      label: \'Chuva prevista\',\n      data: d48.chuva,\n      yAxisID: \'chuva\',\n      backgroundColor: \'#3b82f6\',\n      borderRadius: 2,\n      order: 2\n    },\n    {\n      type: \'line\',\n      label: \'Maré\',\n      data: d48.mare,\n      yAxisID: \'mare\',\n      borderColor: \'#0f766e\',\n      backgroundColor: \'#0f766e\',\n      borderWidth: 2.5,\n      pointRadius: 0,\n      tension: 0.35,\n      order: 1\n    }\n  ];\n\n  // 2.2 Adiciona a linha de limiar de maré alta, se existir\n  if (d48.limiar_mare !== null) {\n    series.push({\n      type: \'line\',\n      label: \'Limiar de maré alta\',\n      yAxisID: \'mare\',\n      data: d48.rotulos.map(() => d48.limiar_mare),\n      borderColor: \'#d97706\',\n      borderDash: [6, 4],\n      borderWidth: 1.5,\n      pointRadius: 0,\n      order: 0\n    });\n  }\n\n  // Extrai a hora de uma string de data (espera algo como "DD/MM HH:MM")\n  const obterHora = (rotulo) => parseInt(rotulo.split(\' \')[1], 10);\n\n  // 2.3 Plugin customizado (sombrear noites e marcar a virada do dia)\n  const pluginDiasENoites = {\n    id: \'diasENoites\',\n    beforeDatasetsDraw(chart) {\n      const { ctx, chartArea, scales: { x } } = chart;\n      const passo = (x.getPixelForValue(1) - x.getPixelForValue(0)) || 0;\n\n      ctx.save();\n\n      d48.rotulos.forEach((rotulo, i) => {\n        const px = x.getPixelForValue(i);\n        const hora = obterHora(rotulo);\n\n        // Desenha o fundo sombreado da noite (18h às 6h)\n        if (hora >= 18 || hora < 6) {\n          ctx.fillStyle = \'rgba(100, 116, 139, 0.07)\';\n          ctx.fillRect(px - passo / 2, chartArea.top, passo, chartArea.bottom - chartArea.top);\n        }\n\n        // Desenha a linha e o texto indicando o início de um novo dia (00h)\n        if (hora === 0) {\n          ctx.strokeStyle = \'#94a3b8\';\n          ctx.setLineDash([3, 3]);\n\n          ctx.beginPath();\n          ctx.moveTo(px - passo / 2, chartArea.top);\n          ctx.lineTo(px - passo / 2, chartArea.bottom);\n          ctx.stroke();\n\n          ctx.setLineDash([]);\n          ctx.fillStyle = \'#64748b\';\n          ctx.font = \'11px sans-serif\';\n          ctx.fillText(rotulo.split(\' \')[0], px - passo / 2 + 4, chartArea.top + 12);\n        }\n      });\n\n      ctx.restore();\n    }\n  };\n\n  // 2.4 Renderização do Gráfico\n  new Chart(document.getElementById(\'grafico48h\'), {\n    plugins: [pluginDiasENoites],\n    data: {\n      labels: d48.rotulos,\n      datasets: series\n    },\n    options: {\n      responsive: true,\n      maintainAspectRatio: false,\n      interaction: { mode: \'index\', intersect: false },\n      plugins: {\n        legend: {\n          position: \'bottom\',\n          labels: { boxWidth: 12, font: { size: 11 } }\n        },\n        tooltip: {\n          callbacks: {\n            label: (contexto) => {\n              if (contexto.parsed.y === null) return `${contexto.dataset.label}: sem dado`;\n\n              const isChuva = contexto.dataset.yAxisID === \'chuva\';\n              const valorFormatado = isChuva\n                ? formatarValor(contexto.parsed.y, 1, \'mm\')\n                : formatarValor(contexto.parsed.y, 2, \'m\');\n\n              return `${contexto.dataset.label}: ${valorFormatado}`;\n            }\n          }\n        }\n      },\n      scales: {\n        x: {\n          grid: { display: false },\n          ticks: { maxRotation: 0, autoSkip: true, maxTicksLimit: 12 }\n        },\n        chuva: {\n          position: \'left\',\n          beginAtZero: true,\n          suggestedMax: 5,\n          title: { display: true, text: \'chuva (mm/h)\' },\n          ticks: { callback: (valor) => valor.toLocaleString(\'pt-BR\') }\n        },\n        mare: {\n          position: \'right\',\n          grid: { drawOnChartArea: false },\n          title: { display: true, text: \'maré (m)\' },\n          ticks: { callback: (valor) => valor.toLocaleString(\'pt-BR\') }\n        }\n      }\n    }\n  });\n}\n', '// Dashboard: os 8 gráficos. Cada um lê o seu JSON (json_script "d-gN") e só desenha se ele existir.\n(function () {\n  if (!window.Chart) return;\n  const COR = { chuva: \'#2563eb\', critico: \'#dc2626\', mare: \'#0d9488\', normal: \'#94a3b8\', previsto: \'#ea580c\',\n                alto: \'#dc2626\', medio: \'#f59e0b\', anterior: \'#a5b4fc\', atual: \'#7c3aed\' };\n  Chart.defaults.font.family = "\'DM Sans\', system-ui, sans-serif";\n  Chart.defaults.font.size = 11;\n  Chart.defaults.maintainAspectRatio = false;\n  Chart.defaults.plugins.legend.labels.boxWidth = 12;\n\n  function dados(id) {\n    const el = document.getElementById(\'d-\' + id);\n    return el ? JSON.parse(el.textContent) : null;\n  }\n  function linhaConstante(rotulo, valor, n, cor) {\n    return { type: \'line\', label: rotulo, data: Array(n).fill(valor), borderColor: cor, borderDash: [6, 4],\n             borderWidth: 1.5, pointRadius: 0, fill: false };\n  }\n\n  // 1. Chuva x maré nas próximas 48 h\n  const g1 = dados(\'g1\');\n  if (g1) {\n    const series = [\n      { type: \'bar\', label: \'Chuva (mm/h)\', data: g1.chuva, yAxisID: \'y\',\n        backgroundColor: g1.criticas.map((c) => (c ? COR.critico : COR.chuva)) },\n      { type: \'line\', label: \'Maré (m)\', data: g1.mare, yAxisID: \'y2\', borderColor: COR.mare,\n        pointRadius: 0, tension: 0.35, borderWidth: 2 },\n    ];\n    if (g1.limiar_mare !== null) {\n      series.push({ ...linhaConstante(\'Maré alta\', g1.limiar_mare, g1.rotulos.length, COR.mare), yAxisID: \'y2\' });\n    }\n    new Chart(document.getElementById(\'g1\'), {\n      data: { labels: g1.rotulos, datasets: series },\n      options: { interaction: { mode: \'index\', intersect: false },\n        scales: { y: { title: { display: true, text: \'chuva (mm/h)\' }, beginAtZero: true },\n                  y2: { position: \'right\', title: { display: true, text: \'maré (m)\' }, grid: { drawOnChartArea: false } },\n                  x: { ticks: { maxTicksLimit: 16 } } } },\n    });\n  }\n\n  // 2. Quanto falta para o gatilho\n  const g2 = dados(\'g2\');\n  if (g2) {\n    const n = g2.distritos.length;\n    new Chart(document.getElementById(\'g2\'), {\n      data: { labels: g2.distritos, datasets: [\n        { type: \'bar\', label: \'Medida em 72 h\', data: g2.medido_72h, backgroundColor: COR.chuva },\n        { type: \'bar\', label: \'Prevista em 24 h\', data: g2.previsto_24h, backgroundColor: \'#93c5fd\' },\n        linhaConstante(`Solo encharcado (${g2.limiares.encharcado} mm em 72 h)`, g2.limiares.encharcado, n, \'#0f172a\'),\n        linhaConstante(`Chuva forte (${g2.limiares.forte} mm)`, g2.limiares.forte, n, COR.medio),\n        linhaConstante(`Muito forte (${g2.limiares.muito_forte} mm)`, g2.limiares.muito_forte, n, COR.critico),\n      ] },\n      options: { scales: { y: { beginAtZero: true, title: { display: true, text: \'mm\' } } } },\n    });\n  }\n\n  // 3. Chuva dos últimos 30 dias x normal\n  const g3 = dados(\'g3\');\n  if (g3) {\n    new Chart(document.getElementById(\'g3\'), {\n      data: { labels: g3.rotulos, datasets: [\n        { type: \'bar\', label: \'Chuva do dia (mm)\', data: g3.chuva, backgroundColor: COR.chuva },\n        { type: \'line\', label: \'Normal 2014–2024\', data: g3.normal, borderColor: COR.normal, borderWidth: 2,\n          pointRadius: 0, tension: 0.3 },\n      ] },\n      options: { interaction: { mode: \'index\', intersect: false },\n        scales: { y: { beginAtZero: true, title: { display: true, text: \'mm\' } }, x: { ticks: { maxTicksLimit: 10 } } } },\n    });\n  }\n\n  // 4. Onde estamos no ano: atendimentos\n  const g4 = dados(\'g4\');\n  if (g4) {\n    const ponto = g4.rotulos.map((_, i) => (i + 1 === g4.semana_atual ? g4.previsto : null));\n    new Chart(document.getElementById(\'g4\'), {\n      data: { labels: g4.rotulos, datasets: [\n        { type: \'line\', label: \'Maior ano\', data: g4.maximo, borderColor: \'transparent\', pointRadius: 0,\n          backgroundColor: \'rgba(148,163,184,0.25)\', fill: \'+1\' },\n        { type: \'line\', label: \'Menor ano\', data: g4.minimo, borderColor: \'transparent\', pointRadius: 0, fill: false },\n        { type: \'line\', label: \'Média 2015–2024\', data: g4.media, borderColor: \'#334155\', borderWidth: 2,\n          pointRadius: 0, tension: 0.3 },\n        { type: \'line\', label: \'Previsão desta semana\', data: ponto, borderColor: COR.previsto,\n          backgroundColor: COR.previsto, pointRadius: 7, showLine: false },\n      ] },\n      options: { interaction: { mode: \'index\', intersect: false },\n        plugins: { legend: { labels: { filter: (item) => item.text !== \'Menor ano\' } } },\n        scales: { y: { beginAtZero: true, title: { display: true, text: \'atendimentos/semana\' } },\n                  x: { ticks: { maxTicksLimit: 13 } } } },\n    });\n  }\n\n  // 5. Arboviroses ano a ano\n  const g5 = dados(\'g5\');\n  if (g5) {\n    new Chart(document.getElementById(\'g5\'), {\n      data: { labels: g5.rotulos, datasets: [\n        { type: \'line\', label: String(g5.ano_anterior), data: g5.anterior, borderColor: COR.anterior,\n          borderWidth: 2, pointRadius: 0, tension: 0.3 },\n        { type: \'line\', label: String(g5.ano), data: g5.atual, borderColor: COR.atual, borderWidth: 3,\n          pointRadius: 0, tension: 0.3, backgroundColor: \'rgba(124,58,237,0.1)\', fill: true },\n      ] },\n      options: { interaction: { mode: \'index\', intersect: false },\n        scales: { y: { beginAtZero: true, title: { display: true, text: \'casos estimados\' } },\n                  x: { ticks: { maxTicksLimit: 14 } } } },\n    });\n  }\n\n  // 7. Alertas dos últimos 30 dias\n  const g7 = dados(\'g7\');\n  if (g7) {\n    new Chart(document.getElementById(\'g7\'), {\n      type: \'bar\',\n      data: { labels: g7.rotulos, datasets: [\n        { label: \'Alto\', data: g7.alto, backgroundColor: COR.alto },\n        { label: \'Médio\', data: g7.medio, backgroundColor: COR.medio },\n      ] },\n      options: { scales: { x: { stacked: true, ticks: { maxTicksLimit: 10 } },\n                           y: { stacked: true, beginAtZero: true, ticks: { precision: 0 } } } },\n    });\n  }\n\n  // 8. Demanda prevista por distrito\n  const g8 = dados(\'g8\');\n  if (g8) {\n    const series = [\n      { label: \'Previsto\', data: g8.previsto, backgroundColor: COR.previsto },\n      { label: \'Normal da época\', data: g8.normal, backgroundColor: COR.normal },\n    ];\n    if (g8.real) series.push({ label: \'Real\', data: g8.real, backgroundColor: \'#334155\' });\n    new Chart(document.getElementById(\'g8\'), {\n      type: \'bar\',\n      data: { labels: g8.distritos, datasets: series },\n      options: { scales: { y: { beginAtZero: true, title: { display: true, text: \'atendimentos na semana\' } } } },\n    });\n  }\n})();\n'), 'apps/painel/templates/painel/dashboard.html': ('{% extends \'components/app-shell.html\' %}\n{% load static %}\n\n{% block title %}Dashboard{% endblock %}\n{% block page_title %}Dashboard{% endblock %}\n\n{% block head_extra %}\n  <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>\n{% endblock %}\n\n{% block content %}\n        \n          <!-- Cabeçalho da Página -->\n          <header class="mb-8 flex flex-col justify-between gap-4 border-b border-slate-200 pb-6 sm:flex-row sm:items-center">\n            <div class="min-w-0">\n              <h1 class="truncate text-3xl font-extrabold tracking-tight text-brand-navy">Visão Geral</h1>\n              {% if meteo %}\n              <p class="mt-1 flex items-center gap-2 text-sm text-slate-500">\n                <i data-lucide="clock" class="w-4 h-4"></i>\n                Última leitura dos pluviômetros: <span class="font-medium">{{ meteo.coletado_em|date:"d/m/Y" }} às {{ meteo.coletado_em|time:"H:i" }}</span>\n              </p>\n              {% else %}\n              <p class="mt-1 text-sm text-slate-500">Sem coleta meteorológica — rode <code>python -m etl cemaden previsao</code></p>\n              {% endif %}\n            </div>\n          </header>\n\n          {% if erro_banco %}\n          <div class="mb-6 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800 shadow-sm">\n            <div class="flex items-center gap-2 font-semibold"><i data-lucide="alert-triangle" class="w-5 h-5"></i> Erro de Conexão</div>\n            <p class="mt-1">Não foi possível conectar à base de dados. Os indicadores reais estão indisponíveis — confira a conexão e o <code>MONGO_URI</code>.</p>\n          </div>\n          {% endif %}\n\n\n          <!-- Seção de Métricas (KPIs) -->\n          <section class="grid gap-5 sm:grid-cols-2 xl:grid-cols-4">\n            <!-- Card 1: arboviroses (InfoDengue) -->\n            <article class="group rounded-xl border border-slate-200 bg-white p-6 shadow-sm transition-all hover:shadow-md"\n                     title="Casos novos na semana epidemiológica (dengue, chikungunya e zika), estimados pelo InfoDengue com correção do atraso de notificação. Dado municipal e semanal.">\n              <div class="flex items-start justify-between">\n                <div>\n                  <p class="flex items-center gap-2 text-sm font-semibold text-slate-500">Arboviroses <span class="inline-flex items-center rounded-full bg-emerald-100 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-emerald-800">InfoDengue</span></p>\n                  <p class="mt-2 text-4xl font-extrabold text-slate-900 tracking-tight">{% if arboviroses %}{{ arboviroses.estimados }}{% else %}--{% endif %}{% if arboviroses %} <small class="text-sm font-medium text-slate-400">estimados</small>{% endif %}</p>\n                </div>\n                <div class="grid size-12 place-items-center rounded-xl bg-brand-tealsoft text-brand-teal transition-transform group-hover:scale-105">\n                  <i data-lucide="bug" class="w-6 h-6"></i>\n                </div>\n              </div>\n              {% if arboviroses %}\n              <p class="mt-2 text-xs text-slate-500">entre {{ arboviroses.estimados_min }} e {{ arboviroses.estimados_max }} · {{ arboviroses.notificados }} já notificados</p>\n              <p class="mt-3 flex flex-wrap items-center gap-2 text-xs text-slate-600">\n                <span class="inline-flex items-center rounded-md px-2 py-1 text-[11px] font-bold\n                  {% if arboviroses.nivel == 4 %}bg-red-100 text-red-800{% elif arboviroses.nivel == 3 %}bg-orange-100 text-orange-800{% elif arboviroses.nivel == 2 %}bg-yellow-100 text-yellow-800{% else %}bg-green-100 text-green-800{% endif %}"\n                  title="{{ arboviroses.nivel_texto }} ({{ arboviroses.nivel_doenca }})">{{ arboviroses.nivel_nome }}</span>\n                SE {{ arboviroses.semana }} · {{ arboviroses.inicio|date:"d/m" }} a {{ arboviroses.fim|date:"d/m" }}\n              </p>\n              {% if arboviroses.ano_anterior is not None %}\n              <p class="mt-1 text-[11px] text-slate-400">mesma semana de {{ arboviroses.ano|add:"-1" }}: {{ arboviroses.ano_anterior }}</p>\n              {% endif %}\n              {% else %}\n              <p class="mt-3 text-xs font-medium text-slate-500">rode <code>python -m etl infodengue</code></p>\n              {% endif %}\n            </article>\n\n            <!-- Card 2: Alertas Sugeridos -->\n            <article class="group rounded-xl border border-slate-200 bg-white p-6 shadow-sm transition-all hover:shadow-md">\n              <div class="flex items-start justify-between">\n                <div>\n                  <p class="flex items-center gap-2 text-sm font-semibold text-slate-500">Alertas Sugeridos <span class="inline-flex items-center rounded-full bg-slate-100 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-slate-600" title="Gerados automaticamente pelos gatilhos de chuva e maré. Um operador confirma.">Auto</span></p>\n                  <p class="mt-2 text-4xl font-extrabold text-slate-900 tracking-tight">{% if alertas is None %}--{% else %}{{ alertas|length }}{% endif %}</p>\n                </div>\n                <div class="grid size-12 place-items-center rounded-xl bg-red-50 text-red-600 transition-transform group-hover:scale-105">\n                  <i data-lucide="siren" class="w-6 h-6"></i>\n                </div>\n              </div>\n              <p class="mt-4 text-sm font-medium {% if alertas %}text-red-600{% else %}text-slate-500{% endif %}">\n                {% if alertas is None %}sem dados para avaliar\n                {% elif alertas %}{{ alertas_altos }} de nível alto\n                {% else %}<span class="flex items-center gap-1 text-green-600"><i data-lucide="check-circle" class="w-4 h-4"></i> Nenhum gatilho acionado</span>{% endif %}\n              </p>\n            </article>\n\n            <!-- Card 3: Distritos -->\n            <article class="group rounded-xl border border-slate-200 bg-white p-6 shadow-sm transition-all hover:shadow-md">\n              <div class="flex items-start justify-between">\n                <div>\n                  <p class="text-sm font-semibold text-slate-500">Distritos Monitorados</p>\n                  <p class="mt-2 text-4xl font-extrabold text-slate-900 tracking-tight">{{ total_distritos|default:"--" }}</p>\n                </div>\n                <div class="grid size-12 place-items-center rounded-xl bg-green-50 text-green-600 transition-transform group-hover:scale-105">\n                  <i data-lucide="crosshair" class="w-6 h-6"></i>\n                </div>\n              </div>\n              <p class="mt-4 text-sm font-medium text-slate-500">{{ total_unidades|default:"--" }} unidades de saúde na rede</p>\n            </article>\n\n            <!-- Card 4: Ações em Andamento -->\n            <article class="group rounded-xl border border-slate-200 bg-white p-6 shadow-sm transition-all hover:shadow-md">\n              <div class="flex items-start justify-between">\n                <div>\n                  <p class="flex items-center gap-2 text-sm font-semibold text-slate-500">Ações em Andamento</p>\n                  <p class="mt-2 text-4xl font-extrabold text-slate-900 tracking-tight">{{ acoes_andamento|default:"0" }}</p>\n                </div>\n                <div class="grid size-12 place-items-center rounded-xl bg-amber-50 text-amber-600 transition-transform group-hover:scale-105">\n                  <i data-lucide="bell-ring" class="w-6 h-6"></i>\n                </div>\n              </div>\n              <p class="mt-4 flex items-center justify-between text-sm font-medium text-slate-500">\n                <span>{{ equipes_mobilizadas|default:"0" }} equipe{{ equipes_mobilizadas|pluralize }} mobilizada{{ equipes_mobilizadas|pluralize }}</span>\n                <a class="text-brand-teal hover:text-brand-tealdark hover:underline font-semibold" href="{% url \'acoes\' %}">Ver detalhes &rarr;</a>\n              </p>\n            </article>\n          </section>\n\n          <!-- Monitoramento Meteorológico -->\n          <section class="mt-6 rounded-xl border border-slate-200 bg-white p-6 shadow-sm">\n            <div class="grid gap-6 md:grid-cols-[minmax(0,1fr)_auto] md:items-center">\n              <div>\n                <div class="mb-4 flex items-center gap-4">\n                  <div class="grid size-12 shrink-0 place-items-center rounded-xl bg-brand-tealsoft text-brand-teal">\n                    <i data-lucide="cloud-rain" class="w-6 h-6"></i>\n                  </div>\n                  <div>\n                    <h2 class="text-lg font-bold text-slate-900">Monitoramento Meteorológico</h2>\n                    <p class="text-sm text-slate-500">Chuva: {{ meteo.fonte_chuva|default:"CEMADEN/MCTIC" }} · Previsão: Open-Meteo</p>\n                  </div>\n                </div>\n                <div class="flex flex-wrap items-center gap-3">\n                  {% if not meteo %}\n                  <span class="inline-flex items-center gap-1 rounded-md bg-slate-100 px-2.5 py-1 text-xs font-semibold text-slate-700"><i data-lucide="help-circle" class="w-3 h-3"></i> Sem dados</span>\n                  {% elif meteo.desatualizado %}\n                  <span class="inline-flex items-center gap-1 rounded-md bg-amber-100 px-2.5 py-1 text-xs font-semibold text-amber-800"><i data-lucide="clock" class="w-3 h-3"></i> Desatualizado há {{ meteo.idade_horas }}h</span>\n                  {% else %}\n                  <span class="inline-flex items-center gap-1 rounded-md bg-green-100 px-2.5 py-1 text-xs font-semibold text-green-800"><i data-lucide="check-circle-2" class="w-3 h-3"></i> Atualizado</span>\n                  {% endif %}\n                </div>\n              </div>\n\n              <div class="grid gap-4 sm:grid-cols-2 xl:min-w-[48rem] xl:grid-cols-4">\n                <div class="rounded-xl border border-slate-100 bg-slate-50 p-5 transition-colors hover:bg-slate-100">\n                  <div class="flex items-center gap-2 text-xs font-semibold uppercase tracking-wide text-slate-500">\n                    <i data-lucide="cloud-rain" class="w-4 h-4 text-brand-teal"></i> Medido (24h)\n                  </div>\n                  <strong class="mt-2 block text-3xl font-extrabold text-slate-900">{% if meteo.chuva_24h is not None %}{{ meteo.chuva_24h|floatformat:1 }}{% else %}--{% endif %}<span class="text-base font-semibold text-slate-500 ml-1">mm</span></strong>\n                  <p class="mt-2 text-xs font-bold text-slate-700">{{ meteo.chuva_24h_classe|default:"-" }}</p>\n                  <p class="text-[11px] text-slate-500">{{ meteo.chuva_24h_zona|default:"-" }}</p>\n                </div>\n                <div class="rounded-xl border border-blue-200 bg-blue-50 p-5 transition-colors hover:bg-blue-100/50">\n                  <div class="flex items-center gap-2 text-xs font-semibold uppercase tracking-wide text-blue-700">\n                    <i data-lucide="cloud-drizzle" class="w-4 h-4"></i> Previsão (24h)\n                  </div>\n                  <strong class="mt-2 block text-3xl font-extrabold text-blue-900">{% if meteo.previsao_24h is not None %}{{ meteo.previsao_24h|floatformat:1 }}{% else %}--{% endif %}<span class="text-base font-semibold text-blue-700 ml-1">mm</span></strong>\n                  <p class="mt-2 text-xs font-bold text-blue-900">{{ meteo.previsao_24h_classe|default:"-" }}</p>\n                  <p class="text-[11px] text-blue-700">{% if meteo.previsao_24h is not None %}{{ meteo.previsao_24h_zona }}{% else %}aguardando modelo{% endif %}</p>\n                </div>\n                <div class="rounded-xl border border-slate-100 bg-slate-50 p-5 transition-colors hover:bg-slate-100">\n                  <div class="flex items-center gap-2 text-xs font-semibold uppercase tracking-wide text-slate-500">\n                    <i data-lucide="thermometer-sun" class="w-4 h-4 text-orange-500"></i> Temperatura\n                  </div>\n                  <strong class="mt-2 block text-3xl font-extrabold text-slate-900">{% if meteo.temp_min is not None %}{{ meteo.temp_min|floatformat:0 }}–{{ meteo.temp_max|floatformat:0 }}{% else %}--{% endif %}<span class="text-base font-semibold text-slate-500 ml-1">°C</span></strong>\n                  <p class="mt-2 text-xs text-slate-500">Mínima e Máxima</p>\n                </div>\n                <div class="rounded-xl border p-5 transition-colors {% if mare.proxima_alta %}border-amber-200 bg-amber-50 hover:bg-amber-100/50{% else %}border-slate-100 bg-slate-50 hover:bg-slate-100{% endif %}"\n                     title="Altura em relação ao nível médio do mar. Modelo Open-Meteo, célula ~16 km mar adentro.">\n                  <div class="flex items-center gap-2 text-xs font-semibold uppercase tracking-wide text-slate-500">\n                    <i data-lucide="waves" class="w-4 h-4 {% if mare.proxima_alta %}text-amber-600{% else %}text-blue-500{% endif %}"></i> Maré Cheia\n                  </div>\n                  <strong class="mt-2 block text-3xl font-extrabold text-slate-900">{% if mare %}{{ mare.proxima_nivel|floatformat:2 }}{% else %}--{% endif %}<span class="text-base font-semibold text-slate-500 ml-1">m</span></strong>\n                  <p class="mt-2 text-xs font-bold {% if mare.proxima_alta %}text-amber-800{% else %}text-slate-700{% endif %}">{% if mare %}{% if mare.proxima_alta %}Sizígia (Alta){% else %}Normal{% endif %}{% else %}-{% endif %}</p>\n                  <p class="text-[11px] text-slate-500">{% if mare %}{{ mare.proxima_quando }}{% else %}rode <code>python -m etl mare</code>{% endif %}</p>\n                </div>\n              </div>\n            </div>\n          </section>\n\n          {% include "painel/_matriz.html" %}\n\n          <!-- Gráficos e Avisos -->\n          <div class="mt-6 grid gap-6 xl:grid-cols-[minmax(0,1fr)_380px]">\n\n            <section class="rounded-xl border border-slate-200 bg-white min-w-0 p-6 shadow-sm">\n              <div class="mb-6 flex items-center gap-4">\n                <div class="grid size-10 shrink-0 place-items-center rounded-lg bg-brand-tealsoft text-brand-teal">\n                  <i data-lucide="activity" class="w-5 h-5"></i>\n                </div>\n                <div>\n                  <h2 class="text-lg font-bold text-slate-900">Próximas 48h — Chuva × Maré</h2>\n                  <p class="text-sm text-slate-500">Faixas cinza: noite (18h às 6h) · Linha tracejada: limiar de maré alta</p>\n                </div>\n              </div>\n              {% if proximas_48h %}\n              <div class="relative h-80 w-full rounded-lg border border-slate-100 bg-slate-50/50 p-2">\n                <canvas id="grafico48h"></canvas>\n              </div>\n              {{ proximas_48h|json_script:"dados-48h" }}\n              {% else %}\n              <div class="grid h-80 place-items-center rounded-xl border-2 border-dashed border-slate-200 bg-slate-50 text-sm font-medium text-slate-500">\n                Sem previsão — rode <code class="mx-1 rounded bg-slate-200 px-1 py-0.5">python -m etl previsao mare</code>\n              </div>\n              {% endif %}\n            </section>\n\n            <aside class="flex flex-col gap-5">\n              <!-- Avisos INMET -->\n              <div class="rounded-xl border {% if avisos %}border-orange-200 bg-orange-50{% else %}border-slate-200 bg-white shadow-sm{% endif %} p-6">\n                <h2 class="flex items-center gap-2 text-sm font-bold uppercase tracking-wide {% if avisos %}text-orange-800{% else %}text-slate-500{% endif %}">\n                  <i data-lucide="radio" class="w-4 h-4"></i> Avisos Oficiais (INMET)\n                </h2>\n                <div class="mt-4 flex flex-col gap-3">\n                  {% for a in avisos %}\n                  <div class="rounded-lg bg-white/60 p-3 shadow-sm">\n                    <span class="inline-flex items-center rounded-md px-2 py-1 text-[10px] font-extrabold uppercase tracking-wide {% if a.nivel == 3 %}bg-red-100 text-red-800{% elif a.nivel == 2 %}bg-orange-100 text-orange-800{% else %}bg-yellow-100 text-yellow-800{% endif %}">{{ a.severidade }}</span>\n                    <p class="mt-2 text-sm font-bold text-slate-900">{{ a.evento }}</p>\n                    <p class="mt-1 text-xs text-slate-600">{{ a.inicio|date:"d/m H:i" }} a {{ a.fim|date:"d/m H:i" }}{% if a.link %} · <a class="font-semibold underline hover:text-brand-navy" href="{{ a.link }}" target="_blank" rel="noopener">Ver aviso</a>{% endif %}</p>\n                  </div>\n                  {% empty %}\n                  <p class="text-sm text-slate-500">Nenhum aviso em vigor para o Recife.</p>\n                  {% endfor %}\n                </div>\n              </div>\n\n              <!-- Alertas do Sistema -->\n              <div class="rounded-xl border border-slate-200 bg-white p-6 shadow-sm flex-1">\n                <h2 class="flex items-center gap-2 text-sm font-bold uppercase tracking-wide text-slate-800">\n                  <i data-lucide="cpu" class="w-4 h-4 text-brand-teal"></i> Gatilhos do Sistema\n                </h2>\n                <div class="mt-4">\n                  {% if alertas is None %}\n                  <p class="rounded-lg bg-slate-50 p-4 text-sm text-slate-500">Sem dados meteorológicos para avaliar.</p>\n                  {% elif alertas %}\n                  <div class="flex flex-col gap-3">\n                    {% for a in alertas %}\n                    <div class="rounded-lg border border-slate-100 bg-slate-50 p-3">\n                      <div class="flex items-center justify-between gap-2">\n                        <span class="inline-flex items-center rounded-md px-2 py-1 text-[10px] font-bold uppercase tracking-wide {% if a.nivel == \'ALTO\' %}bg-red-100 text-red-800{% else %}bg-amber-100 text-amber-800{% endif %}">{{ a.nivel }}</span>\n                        <span class="text-xs font-semibold text-slate-500">{{ a.zona }}</span>\n                      </div>\n                      <h3 class="mt-2 text-sm font-bold text-slate-900">Risco de {{ a.tipo|lower }}</h3>\n                      <p class="mt-1 text-xs text-slate-600">{{ a.motivo }}</p>\n                    </div>\n                    {% endfor %}\n                  </div>\n                  {% else %}\n                  <div class="flex flex-col items-center justify-center rounded-lg border border-green-100 bg-green-50 p-6 text-center">\n                    <i data-lucide="check-circle" class="w-8 h-8 text-green-500 mb-2"></i>\n                    <p class="text-sm font-medium text-green-800">Tudo calmo. Previsão de chuva e maré dentro da normalidade.</p>\n                  </div>\n                  {% endif %}\n                </div>\n              </div>\n            </aside>\n          </div>\n\n          <!-- Histórico Diário -->\n          <section class="mt-6 rounded-xl border border-slate-200 bg-white min-w-0 p-6 shadow-sm">\n              <div class="mb-6 flex items-center gap-4">\n                <div class="grid size-10 shrink-0 place-items-center rounded-lg bg-slate-100 text-slate-600">\n                  <i data-lucide="bar-chart-3" class="w-5 h-5"></i>\n                </div>\n                <div>\n                  <h2 class="text-lg font-bold text-slate-900">Histórico de Chuva — Últimos 14 dias</h2>\n                  <p class="text-sm text-slate-500">Média dos pluviômetros (barras) e pior leitura do dia (linha).</p>\n                </div>\n              </div>\n\n              {% if chuva_diaria %}\n              <div class="relative h-72 w-full">\n                <canvas id="graficoChuva"></canvas>\n              </div>\n              {{ chuva_diaria|json_script:"dados-chuva-diaria" }}\n              {% else %}\n              <div class="grid h-72 place-items-center rounded-xl border-2 border-dashed border-slate-200 bg-slate-50 text-sm font-medium text-slate-500">\n                Sem dados de chuva — rode <code class="mx-1 rounded bg-slate-200 px-1 py-0.5">python -m etl cemaden</code>\n              </div>\n              {% endif %}\n          </section>\n      \n{% endblock %}\n\n{% block scripts %}\n  <script src="{% static \'painel/dashboard.js\' %}"></script>\n{% endblock %}\n', '{% extends "components/app-shell.html" %}\n{% load static %}\n\n{% block title %}Dashboard{% endblock %}\n{% block page_title %}Dashboard{% endblock %}\n\n{% block head_extra %}\n  <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js"></script>\n  <style>\n    .calor td { width: 7%; height: 2.25rem; text-align: center; font-size: .7rem; font-weight: 600; }\n    .calor .t1 { background: #e0f2fe; color: #075985; } .calor .t2 { background: #fef3c7; color: #92400e; }\n    .calor .t3 { background: #fdba74; color: #7c2d12; } .calor .t4 { background: #dc2626; color: #fff; }\n    .calor .vazio { background: #f1f5f9; color: #94a3b8; } .calor .atual { outline: 3px solid #0f172a; outline-offset: -3px; }\n  </style>\n{% endblock %}\n\n{% block content %}\n<header class="mb-6 border-b border-slate-200 pb-5">\n  <h1 class="text-3xl font-extrabold tracking-tight text-brand-navy">Visão Geral</h1>\n  <p class="mt-1 text-sm text-slate-500">Chuva, maré, demanda e saúde do Recife em 8 gráficos.</p>\n</header>\n{% include "painel/_saude.html" %}\n\n{% if erro_banco %}\n<div class="mb-6 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800">\n  <b>Sem conexão com o banco de dados.</b> Os gráficos que dependem do MongoDB estão vazios — confira o <code>MONGO_URI</code>.\n</div>\n{% endif %}\n\n<!-- Números do topo -->\n<section class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">\n  <div class="rounded-xl border border-slate-200 bg-white p-5 shadow-sm">\n    <p class="text-xs font-bold uppercase tracking-wide text-slate-500">Chuva nas últimas 24 h</p>\n    <p class="mt-2 text-4xl font-extrabold text-slate-900">{% if indicadores.chuva_24h is not None %}{{ indicadores.chuva_24h|floatformat:1 }}<small class="ml-1 text-base text-slate-500">mm</small>{% else %}--{% endif %}</p>\n    <p class="mt-1 text-xs text-slate-500">{{ indicadores.chuva_24h_zona|default:"pior pluviômetro" }}</p>\n  </div>\n  <div class="rounded-xl border border-blue-200 bg-blue-50 p-5">\n    <p class="text-xs font-bold uppercase tracking-wide text-blue-700">Previsão próximas 24 h</p>\n    <p class="mt-2 text-4xl font-extrabold text-blue-900">{% if indicadores.previsao_24h is not None %}{{ indicadores.previsao_24h|floatformat:1 }}<small class="ml-1 text-base text-blue-700">mm</small>{% else %}--{% endif %}</p>\n    <p class="mt-1 text-xs text-blue-700">{{ indicadores.previsao_24h_zona|default:"distrito com maior previsão" }}</p>\n  </div>\n  <div class="rounded-xl border {% if indicadores.sem_acao %}border-red-200 bg-red-50{% else %}border-slate-200 bg-white shadow-sm{% endif %} p-5">\n    <p class="text-xs font-bold uppercase tracking-wide {% if indicadores.sem_acao %}text-red-700{% else %}text-slate-500{% endif %}">Alertas abertos</p>\n    <p class="mt-2 text-4xl font-extrabold text-slate-900">{{ indicadores.alertas_abertos|default_if_none:"--" }}</p>\n    <p class="mt-1 text-xs {% if indicadores.sem_acao %}font-semibold text-red-700{% else %}text-slate-500{% endif %}">{% if indicadores.sem_acao %}{{ indicadores.sem_acao }} sem nenhuma ação registrada{% else %}todos com ação registrada{% endif %}</p>\n  </div>\n  <div class="rounded-xl border border-violet-200 bg-violet-50 p-5">\n    <p class="text-xs font-bold uppercase tracking-wide text-violet-700">Arboviroses na semana</p>\n    <p class="mt-2 text-4xl font-extrabold text-violet-900">{{ indicadores.arbo_estimados|default_if_none:"--" }}</p>\n    <p class="mt-1 text-xs text-violet-700">{% if indicadores.arbo_estimados is not None %}casos estimados · SE {{ indicadores.arbo_semana }} · nível {{ indicadores.arbo_nivel }}{% else %}rode <code>python -m etl infodengue</code>{% endif %}</p>\n  </div>\n</section>\n\n<!-- Linha 1: agora -->\n<section class="mt-6 rounded-xl border border-slate-200 bg-white p-6 shadow-sm">\n  <h2 class="text-lg font-bold text-slate-900">1 · Chuva × maré nas próximas 48 h</h2>\n  <p class="text-sm text-slate-500">Barras: chuva prevista por hora{% if g1.zona %} ({{ g1.zona }}, distrito com maior previsão){% endif %}. Linha: maré. <b class="text-red-700">Barras vermelhas</b>: chuva moderada com maré alta ao mesmo tempo.</p>\n  {% if g1 %}\n  {% if g1.horas_criticas %}<p class="mt-2 inline-block rounded-md bg-red-100 px-2 py-1 text-xs font-bold text-red-800">{{ g1.horas_criticas }} hora{{ g1.horas_criticas|pluralize }} crítica{{ g1.horas_criticas|pluralize }} nas próximas 48 h</p>{% endif %}\n  <div class="relative mt-3 h-72"><canvas id="g1"></canvas></div>{{ g1|json_script:"d-g1" }}\n  {% else %}<div class="mt-3 grid h-40 place-items-center rounded-lg bg-slate-50 text-sm text-slate-500">Sem previsão — rode <code class="mx-1">python -m etl previsao mare</code></div>{% endif %}\n</section>\n\n<section class="mt-6 grid gap-6 xl:grid-cols-2">\n  <div class="min-w-0 rounded-xl border border-slate-200 bg-white p-6 shadow-sm">\n    <h2 class="text-lg font-bold text-slate-900">2 · Quanto falta para o gatilho</h2>\n    <p class="text-sm text-slate-500">Chuva medida em 72 h e prevista em 24 h por distrito, com as linhas dos limiares dos gatilhos.</p>\n    {% if g2 %}<div class="relative mt-3 h-72"><canvas id="g2"></canvas></div>{{ g2|json_script:"d-g2" }}\n    {% else %}<div class="mt-3 grid h-40 place-items-center rounded-lg bg-slate-50 text-sm text-slate-500">Sem dados de chuva por distrito.</div>{% endif %}\n  </div>\n  <div class="min-w-0 rounded-xl border border-slate-200 bg-white p-6 shadow-sm">\n    <h2 class="text-lg font-bold text-slate-900">3 · Chuva dos últimos 30 dias × normal</h2>\n    <p class="text-sm text-slate-500">Barras: pior pluviômetro do dia. Linha: média do mesmo dia em 2014–2024.</p>\n    {% if g3 %}\n    {% if g3.razao %}<p class="mt-2 inline-block rounded-md px-2 py-1 text-xs font-bold {% if g3.razao >= 1.3 %}bg-red-100 text-red-800{% elif g3.razao >= 1 %}bg-amber-100 text-amber-800{% else %}bg-sky-100 text-sky-800{% endif %}">{{ g3.total_mm|floatformat:0 }} mm no período · normal {{ g3.normal_mm|floatformat:0 }} mm</p>{% endif %}\n    <div class="relative mt-3 h-64"><canvas id="g3"></canvas></div>{{ g3|json_script:"d-g3" }}\n    {% else %}<div class="mt-3 grid h-40 place-items-center rounded-lg bg-slate-50 text-sm text-slate-500">Sem leituras — rode <code class="mx-1">python -m etl cemaden</code></div>{% endif %}\n  </div>\n</section>\n\n<!-- Linha 2: fora do normal? -->\n<section class="mt-6 grid gap-6 xl:grid-cols-2">\n  <div class="min-w-0 rounded-xl border border-slate-200 bg-white p-6 shadow-sm">\n    <h2 class="text-lg font-bold text-slate-900">4 · Onde estamos no ano: atendimentos</h2>\n    <p class="text-sm text-slate-500">Atendimentos reativos da Defesa Civil por semana (cidade): média 2015–2024 e faixa do menor ao maior ano. Ponto laranja: previsão do modelo{% if g4.semana_atual %} (semana {{ g4.semana_atual }}){% endif %}.</p>\n    {% if g4 %}\n    {% if g4.previsto is not None and not g4.completa %}<p class="mt-2 rounded-md bg-amber-50 p-2 text-xs text-amber-900">Previsão só pelo calendário: os dados da Defesa Civil no banco vão até 2024.</p>{% endif %}\n    <div class="relative mt-3 h-64"><canvas id="g4"></canvas></div>{{ g4|json_script:"d-g4" }}\n    {% else %}<div class="mt-3 grid h-40 place-items-center rounded-lg bg-slate-50 text-sm text-slate-500">Sem histórico — rode <code class="mx-1">python -m etl.derivados.ml_distrito_dia</code></div>{% endif %}\n  </div>\n  <div class="min-w-0 rounded-xl border border-slate-200 bg-white p-6 shadow-sm">\n    <h2 class="text-lg font-bold text-slate-900">5 · Arboviroses: {{ g5.ano|default:"este ano" }} × {{ g5.ano_anterior|default:"ano anterior" }}</h2>\n    <p class="text-sm text-slate-500">Casos estimados de dengue, chikungunya e zika por semana epidemiológica (InfoDengue).</p>\n    {% if g5 %}<div class="relative mt-3 h-64"><canvas id="g5"></canvas></div>{{ g5|json_script:"d-g5" }}\n    {% else %}<div class="mt-3 grid h-40 place-items-center rounded-lg bg-slate-50 text-sm text-slate-500">Sem dados — rode <code class="mx-1">python -m etl infodengue</code></div>{% endif %}\n  </div>\n</section>\n\n<!-- Linha 3: calendário -->\n<section class="mt-6 rounded-xl border border-slate-200 bg-white p-6 shadow-sm">\n  <h2 class="text-lg font-bold text-slate-900">6 · Calendário de risco: distrito × mês</h2>\n  <p class="text-sm text-slate-500">Atendimentos do mês em relação à média do distrito (1,0 = mês comum). Contorno: mês atual.</p>\n  {% if g6 %}\n  <div class="mt-3 overflow-x-auto">\n    <table class="calor w-full border-separate" style="border-spacing:3px">\n      <thead><tr><th></th>{% for m in g6.meses %}<th class="text-xs font-semibold uppercase text-slate-500">{{ m }}</th>{% endfor %}</tr></thead>\n      <tbody>{% for l in g6.linhas %}<tr><th class="pr-2 text-left text-xs font-bold text-slate-700 whitespace-nowrap">{{ l.distrito }}</th>\n        {% for c in l.celulas %}<td class="rounded {{ c.tom }}{% if c.atual %} atual{% endif %}">{% if c.valor is not None %}{{ c.valor|floatformat:1 }}{% else %}—{% endif %}</td>{% endfor %}</tr>{% endfor %}</tbody>\n    </table>\n  </div>\n  <p class="mt-2 flex flex-wrap gap-3 text-xs text-slate-500"><span class="calor"><span class="t1 rounded px-1">abaixo de 0,8</span></span><span class="calor"><span class="t2 rounded px-1">0,8–1,2</span></span><span class="calor"><span class="t3 rounded px-1">1,2–1,6</span></span><span class="calor"><span class="t4 rounded px-1">1,6 ou mais</span></span></p>\n  {% else %}<div class="mt-3 grid h-32 place-items-center rounded-lg bg-slate-50 text-sm text-slate-500">Calendário não calculado — rode <code class="mx-1">python -m etl.derivados.calendario</code></div>{% endif %}\n</section>\n\n<!-- Linha 4: operação -->\n<section class="mt-6 grid gap-6 xl:grid-cols-2">\n  <div class="min-w-0 rounded-xl border border-slate-200 bg-white p-6 shadow-sm">\n    <h2 class="text-lg font-bold text-slate-900">7 · Alertas dos últimos 30 dias</h2>\n    <p class="text-sm text-slate-500">Alertas criados por dia, por nível.{% if g7 %} {{ g7.total }} no período{% if g7.sem_acao %} · <b class="text-red-700">{{ g7.sem_acao }} abertos sem ação</b>{% endif %}.{% endif %}</p>\n    {% if g7 %}<div class="relative mt-3 h-64"><canvas id="g7"></canvas></div>{{ g7|json_script:"d-g7" }}\n    {% else %}<div class="mt-3 grid h-40 place-items-center rounded-lg bg-slate-50 text-sm text-slate-500">Sem alertas.</div>{% endif %}\n  </div>\n  <div class="min-w-0 rounded-xl border border-slate-200 bg-white p-6 shadow-sm">\n    <h2 class="text-lg font-bold text-slate-900">8 · Demanda prevista por distrito</h2>\n    <p class="text-sm text-slate-500">{% if g8 %}Semana de {{ g8.inicio }} a {{ g8.fim }}: atendimentos previstos (XGBoost, erro típico de 39%) contra o normal da época.{% else %}Atendimentos previstos pelo modelo contra o normal da época.{% endif %}</p>\n    {% if g8 %}<div class="relative mt-3 h-64"><canvas id="g8"></canvas></div>{{ g8|json_script:"d-g8" }}\n    {% else %}<div class="mt-3 grid h-40 place-items-center rounded-lg bg-slate-50 text-sm text-slate-500">Sem previsão — rode <code class="mx-1">python -m ml.demanda --prever</code></div>{% endif %}\n  </div>\n</section>\n{% endblock %}\n\n{% block scripts %}\n  <script src="{% static \'painel/dashboard.js\' %}"></script>\n{% endblock %}\n'), 'apps/painel/views.py': ('"""Dashboard: situação do dia."""\n\nimport logging\nimport statistics\nfrom datetime import timedelta\nfrom datetime import timezone as dt_timezone\nfrom django.shortcuts import redirect, render\nfrom django.utils import timezone\nfrom pymongo.errors import PyMongoError\nfrom dominio import limiares\nfrom dominio.mare import preamares\nimport csv\n\nfrom django.http import HttpResponse\n\nfrom apps.alertas.models import AcaoResposta\nfrom apps.painel.saude import saude_dos_dados\nfrom apps.painel.situacao import resumo_geral, situacao_por_distrito\nfrom apps.fontes import painel_chuva\nfrom apps.fontes.resumo_mare import resumo_mare\nfrom apps.fontes.repositorios import arboviroses as repo_arboviroses\nfrom apps.fontes.repositorios import mare as repo_mare\nfrom apps.fontes.repositorios import referencia as repo_referencia\nfrom apps.fontes.repositorios.conexao import BANCO, get_mongo_client\n\nlogger = logging.getLogger(__name__)\n\n\ndef dashboard(request):\n    contexto = {\n        "meteo": None,\n        "chuva_diaria": None,\n        "total_distritos": None,\n        "total_unidades": None,\n        "mare": None,\n        "arboviroses": None,\n        "alertas": None,\n        "proximas_48h": None,\n        "avisos": [],\n        "erro_banco": False,\n    }\n    # A página inicial nunca pode cair por causa do banco: sem conexão,\n    # abre com "--" e um aviso, em vez de erro 500.\n    try:\n        banco = get_mongo_client()[BANCO]\n        contexto["meteo"] = painel_chuva.resumo_meteo()\n        contexto["chuva_diaria"] = painel_chuva.chuva_diaria()\n        if contexto["chuva_diaria"]:\n            contexto["chuva_diaria"]["limiares"] = [\n                {"nome": "Chuva forte", "mm": limiares.CHUVA_FORTE, "cor": "#f97316"},\n                {"nome": "Chuva muito forte", "mm": limiares.CHUVA_MUITO_FORTE, "cor": "#dc2626"},\n            ]\n        contexto["avisos"] = painel_chuva.avisos_oficiais()\n        contexto["arboviroses"] = repo_arboviroses.resumo_semana_cidade()\n\n        mare = resumo_mare()\n        distritos = painel_chuva.distritos_para_gatilhos()\n        contexto["mare"] = mare\n        # None = sem dado para avaliar; [] = avaliado e nenhum gatilho disparou\n        contexto["alertas"] = limiares.avaliar_gatilhos(distritos, mare) if distritos else None\n        contexto["alertas_altos"] = sum(\n            1 for x in contexto["alertas"] or [] if x["nivel"] == "ALTO"\n        )\n        contexto["proximas_48h"] = painel_chuva.proximas_48h(distritos, mare)\n        contexto["total_distritos"] = repo_referencia.total_distritos()\n        contexto["total_unidades"] = repo_referencia.total_unidades()\n    except PyMongoError:\n        logger.exception("Falha ao consultar o MongoDB para o dashboard")\n        contexto["erro_banco"] = True\n    try:\n        contexto["situacao"] = situacao_por_distrito()\n        contexto["faixa"] = resumo_geral(contexto["situacao"], contexto.get("avisos") or [])\n        contexto["saude"] = saude_dos_dados()\n    except Exception:  # noqa: BLE001 - a faixa some, o resto do dashboard continua\n        logger.exception("Falha ao montar a situação dos distritos")\n    try:\n        em_andamento = AcaoResposta.objects.filter(status=AcaoResposta.Status.ANDAMENTO)\n        contexto["acoes_andamento"] = em_andamento.count()\n        contexto["equipes_mobilizadas"] = em_andamento.values("equipe").distinct().count()\n    except Exception:  # noqa: BLE001 - o dashboard nunca cai por causa do PostgreSQL\n        logger.exception("Falha ao consultar o PostgreSQL para o dashboard")\n\n    return render(request, "painel/dashboard.html", contexto)\n\n\ndef situacao_csv(request):\n    """A matriz dos distritos como planilha (requisito: exportar para planilha)."""\n    try:\n        situacao = situacao_por_distrito()\n    except Exception:  # noqa: BLE001 - sem dados, a planilha avisa em vez de dar erro 500\n        logger.exception("Falha ao montar a planilha da situação")\n        return HttpResponse("Dados indisponíveis no momento.", status=503, content_type="text/plain; charset=utf-8")\n    resposta = HttpResponse(content_type="text/csv; charset=utf-8")\n    resposta["Content-Disposition"] = \'attachment; filename="situacao_distritos.csv"\'\n    resposta.write("\\ufeff")  # BOM: o Excel abre os acentos certos\n    w = csv.writer(resposta, delimiter=";")\n    w.writerow(["Distrito", "Situação", "Chuva 24h (mm)", "Pluviômetro", "Chuva 72h (mm)",\n                "Previsão 24h (mm)", "Alertas abertos", "Motivos"])\n    for d in situacao:\n        w.writerow([d["nome"], d["nivel"], d["chuva_24h_mm"], d["estacao_24h"], d["chuva_72h_mm"],\n                    d["previsao_24h_mm"], d["alertas_abertos"], " | ".join(d["motivos"])])\n    return resposta\n\n\nMESES_CURTOS = ["jan", "fev", "mar", "abr", "mai", "jun", "jul", "ago", "set", "out", "nov", "dez"]\n\n\ndef _tom(indice):\n    """Cor da célula pelo índice (mês ÷ média do próprio distrito)."""\n    if indice >= 2:\n        return "muito_alto"\n    if indice >= 1.5:\n        return "alto"\n    if indice >= 1:\n        return "acima"\n    return "abaixo" if indice >= 0.6 else "baixo"\n\n\ndef calendario(request):\n    """Calendário de risco: em que meses cada distrito mais precisa de equipe."""\n    from apps.fontes.repositorios import calendario as repo_calendario\n    linhas, erro, demanda = [], False, None\n    try:\n        demanda = _demanda_da_semana()\n        meses, resumos = repo_calendario.por_mes(), {r["distrito_codigo"]: r for r in repo_calendario.por_distrito()}\n        por_distrito = {}\n        for m in meses:\n            por_distrito.setdefault(m["distrito_codigo"], []).append({\n                **m, "tom": _tom(m["indice"]), "rotulo": MESES_CURTOS[m["mes"] - 1],\n                "dica": (f"{m[\'media_dia\']} atendimentos/dia em média ({m[\'indice\']}x a média do distrito). "\n                         f"Ano mais calmo: {m[\'ano_calmo\']} ({m[\'media_ano_calmo\']}/dia); "\n                         f"mais intenso: {m[\'ano_intenso\']} ({m[\'media_ano_intenso\']}/dia).")})\n        for codigo, celulas in sorted(por_distrito.items()):\n            linhas.append({"nome": celulas[0]["distrito"], "celulas": celulas, "resumo": resumos.get(codigo, {})})\n    except PyMongoError:\n        logger.exception("Falha ao ler o calendário de risco")\n        erro = True\n    return render(request, "painel/calendario.html",\n                  {"linhas": linhas, "meses": MESES_CURTOS, "erro": erro, "demanda": demanda})\n\n\ndef _demanda_da_semana():\n    """Previsão de atendimentos da semana por distrito (ml.demanda), pronta para a tela."""\n    from datetime import date\n    from apps.fontes.repositorios import demanda as repo_demanda\n    docs = repo_demanda.previsao()\n    if not docs:\n        return None\n    for d in docs:\n        v = d.get("variacao")\n        d["tom"] = ("muito_alto" if v is not None and v >= 0.5 else "alto" if v is not None and v >= 0.2\n                    else "abaixo" if v is not None and v <= -0.2 else "normal")\n        d["variacao_pct"] = None if v is None else round(100 * v)\n    primeiro = docs[0]\n    data = lambda iso: date.fromisoformat(iso[:10]).strftime("%d/%m/%Y") if iso else "?"\n    return {"distritos": docs, "inicio": data(primeiro["inicio_semana"]), "fim": data(primeiro["fim_semana"]),\n            "completa": all(d.get("completa") for d in docs), "dados_ate": data(primeiro.get("dados_ate")),\n            "demonstracao": primeiro.get("demonstracao", False)}\n\n\ndef calendario_csv(request):\n    from apps.fontes.repositorios import calendario as repo_calendario\n    try:\n        meses = repo_calendario.por_mes()\n    except PyMongoError:\n        logger.exception("Falha ao ler o calendário de risco para a planilha")\n        return HttpResponse("Dados indisponíveis no momento.", status=503, content_type="text/plain; charset=utf-8")\n    resposta = HttpResponse(content_type="text/csv; charset=utf-8")\n    resposta["Content-Disposition"] = \'attachment; filename="calendario_risco.csv"\'\n    resposta.write("\\ufeff")\n    w = csv.writer(resposta, delimiter=";")\n    w.writerow(["Distrito", "Mês", "Atendimentos reativos por dia (média 2014-2024)", "Índice (mês / média do distrito)",\n                "Ano mais calmo", "Média no ano mais calmo", "Ano mais intenso", "Média no ano mais intenso"])\n    for m in meses:\n        w.writerow([m["distrito"], m["mes"], m["media_dia"], m["indice"], m["ano_calmo"], m["media_ano_calmo"],\n                    m["ano_intenso"], m["media_ano_intenso"]])\n    return resposta\n\n', '"""Dashboard: situação do dia."""\n\nimport logging\nfrom django.shortcuts import render\nfrom pymongo.errors import PyMongoError\nimport csv\n\nfrom django.http import HttpResponse\n\nfrom apps.painel.saude import saude_dos_dados\nfrom apps.painel.situacao import situacao_por_distrito\nfrom apps.fontes import painel_chuva\nfrom apps.fontes.resumo_mare import resumo_mare\n\nlogger = logging.getLogger(__name__)\n\n\ndef dashboard(request):\n    """Dashboard em gráficos: 4 números no topo e 8 gráficos (dados em apps/painel/graficos.py).\n\n    A página nunca cai por causa do banco: cada gráfico é montado à parte e, sem dado, mostra\n    um aviso no lugar."""\n    from apps.painel import graficos\n\n    situacao, proximas, saude, erro_banco = None, None, None, False\n    try:\n        situacao = situacao_por_distrito()\n        proximas = painel_chuva.proximas_48h(painel_chuva.distritos_para_gatilhos(), resumo_mare())\n    except PyMongoError:\n        logger.exception("Falha ao consultar o MongoDB para o dashboard")\n        erro_banco = True\n    except Exception:  # noqa: BLE001\n        logger.exception("Falha ao montar a situação dos distritos")\n    try:\n        saude = saude_dos_dados()\n    except Exception:  # noqa: BLE001\n        logger.exception("Falha ao ler a saúde dos dados")\n    contexto = {"saude": saude, "erro_banco": erro_banco, **graficos.todos(proximas, situacao)}\n    return render(request, "painel/dashboard.html", contexto)\n\n\ndef situacao_csv(request):\n    """A matriz dos distritos como planilha (requisito: exportar para planilha)."""\n    try:\n        situacao = situacao_por_distrito()\n    except Exception:  # noqa: BLE001 - sem dados, a planilha avisa em vez de dar erro 500\n        logger.exception("Falha ao montar a planilha da situação")\n        return HttpResponse("Dados indisponíveis no momento.", status=503, content_type="text/plain; charset=utf-8")\n    resposta = HttpResponse(content_type="text/csv; charset=utf-8")\n    resposta["Content-Disposition"] = \'attachment; filename="situacao_distritos.csv"\'\n    resposta.write("\\ufeff")  # BOM: o Excel abre os acentos certos\n    w = csv.writer(resposta, delimiter=";")\n    w.writerow(["Distrito", "Situação", "Chuva 24h (mm)", "Pluviômetro", "Chuva 72h (mm)",\n                "Previsão 24h (mm)", "Alertas abertos", "Motivos"])\n    for d in situacao:\n        w.writerow([d["nome"], d["nivel"], d["chuva_24h_mm"], d["estacao_24h"], d["chuva_72h_mm"],\n                    d["previsao_24h_mm"], d["alertas_abertos"], " | ".join(d["motivos"])])\n    return resposta\n\n\nMESES_CURTOS = ["jan", "fev", "mar", "abr", "mai", "jun", "jul", "ago", "set", "out", "nov", "dez"]\n\n\ndef _tom(indice):\n    """Cor da célula pelo índice (mês ÷ média do próprio distrito)."""\n    if indice >= 2:\n        return "muito_alto"\n    if indice >= 1.5:\n        return "alto"\n    if indice >= 1:\n        return "acima"\n    return "abaixo" if indice >= 0.6 else "baixo"\n\n\ndef calendario(request):\n    """Calendário de risco: em que meses cada distrito mais precisa de equipe."""\n    from apps.fontes.repositorios import calendario as repo_calendario\n    linhas, erro, demanda = [], False, None\n    try:\n        demanda = _demanda_da_semana()\n        meses, resumos = repo_calendario.por_mes(), {r["distrito_codigo"]: r for r in repo_calendario.por_distrito()}\n        por_distrito = {}\n        for m in meses:\n            por_distrito.setdefault(m["distrito_codigo"], []).append({\n                **m, "tom": _tom(m["indice"]), "rotulo": MESES_CURTOS[m["mes"] - 1],\n                "dica": (f"{m[\'media_dia\']} atendimentos/dia em média ({m[\'indice\']}x a média do distrito). "\n                         f"Ano mais calmo: {m[\'ano_calmo\']} ({m[\'media_ano_calmo\']}/dia); "\n                         f"mais intenso: {m[\'ano_intenso\']} ({m[\'media_ano_intenso\']}/dia).")})\n        for codigo, celulas in sorted(por_distrito.items()):\n            linhas.append({"nome": celulas[0]["distrito"], "celulas": celulas, "resumo": resumos.get(codigo, {})})\n    except PyMongoError:\n        logger.exception("Falha ao ler o calendário de risco")\n        erro = True\n    return render(request, "painel/calendario.html",\n                  {"linhas": linhas, "meses": MESES_CURTOS, "erro": erro, "demanda": demanda})\n\n\ndef _demanda_da_semana():\n    """Previsão de atendimentos da semana por distrito (ml.demanda), pronta para a tela."""\n    from datetime import date\n    from apps.fontes.repositorios import demanda as repo_demanda\n    docs = repo_demanda.previsao()\n    if not docs:\n        return None\n    for d in docs:\n        v = d.get("variacao")\n        d["tom"] = ("muito_alto" if v is not None and v >= 0.5 else "alto" if v is not None and v >= 0.2\n                    else "abaixo" if v is not None and v <= -0.2 else "normal")\n        d["variacao_pct"] = None if v is None else round(100 * v)\n    primeiro = docs[0]\n    data = lambda iso: date.fromisoformat(iso[:10]).strftime("%d/%m/%Y") if iso else "?"\n    return {"distritos": docs, "inicio": data(primeiro["inicio_semana"]), "fim": data(primeiro["fim_semana"]),\n            "completa": all(d.get("completa") for d in docs), "dados_ate": data(primeiro.get("dados_ate")),\n            "demonstracao": primeiro.get("demonstracao", False)}\n\n\ndef calendario_csv(request):\n    from apps.fontes.repositorios import calendario as repo_calendario\n    try:\n        meses = repo_calendario.por_mes()\n    except PyMongoError:\n        logger.exception("Falha ao ler o calendário de risco para a planilha")\n        return HttpResponse("Dados indisponíveis no momento.", status=503, content_type="text/plain; charset=utf-8")\n    resposta = HttpResponse(content_type="text/csv; charset=utf-8")\n    resposta["Content-Disposition"] = \'attachment; filename="calendario_risco.csv"\'\n    resposta.write("\\ufeff")\n    w = csv.writer(resposta, delimiter=";")\n    w.writerow(["Distrito", "Mês", "Atendimentos reativos por dia (média 2014-2024)", "Índice (mês / média do distrito)",\n                "Ano mais calmo", "Média no ano mais calmo", "Ano mais intenso", "Média no ano mais intenso"])\n    for m in meses:\n        w.writerow([m["distrito"], m["mes"], m["media_dia"], m["indice"], m["ano_calmo"], m["media_ano_calmo"],\n                    m["ano_intenso"], m["media_ano_intenso"]])\n    return resposta\n\n')}

raiz = Path.cwd()
assert (raiz / "manage.py").exists(), "rode na raiz do projeto (pasta vigidesastres)"
for nome, (antes, depois) in TROCAS.items():
    atual = (raiz / nome).read_text(encoding="utf-8").replace("\r\n", "\n")
    if atual not in (antes, depois):
        raise SystemExit(f"{nome} está diferente do GitHub (alteração local ou script anterior aplicado); "
                         "nada foi gravado. Rode git checkout -- . e tente de novo.")
for nome, (antes, depois) in TROCAS.items():
    (raiz / nome).write_text(depois, encoding="utf-8", newline="\n")
for nome, texto in NOVOS.items():
    (raiz / nome).parent.mkdir(parents=True, exist_ok=True)
    (raiz / nome).write_text(texto, encoding="utf-8", newline="\n")
print("ok. Agora: python -m pytest -q e python manage.py runserver (abra o Dashboard)")
